/**
 * Signals in message Vehicle_Speed.
 *
 * Signed longitudinal speed. Repeated every 20 ms; ECU receive timeout 100 ms. No application checksum.
 *
 * All signal values are as on the CAN bus.
 */
struct afs_vehicle_speed_t {
    /**
     * Range: 0..15 (0..15 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t alive_counter;

    /**
     * Set only for a usable source sample no older than 250 ms. A saturated value is invalid.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t speed_valid;

    /**
     * Value was clamped to the signed CAN range; SpeedValid must be zero.
     *
     * Range: 0..1 (0..1 -)
     * Scale: 1
     * Offset: 0
     */
    uint8_t speed_saturated;

    /**
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t speed_reserved_bits6_7;

    /**
     * Range: -32768..32767 (-327.68..327.67 m/s)
     * Scale: 0.01
     * Offset: 0
     */
    int16_t longitudinal_speed_mps;

    /**
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t speed_reserved_byte3;

    /**
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint32_t speed_reserved_bytes4_to6;

    /**
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint8_t speed_reserved_byte7;
};

/**
 * Signals in message Vehicle_Steering.
 *
 * Signed ego steering angle. Repeated every 20 ms; ECU receive timeout 100 ms. No application checksum.
 *
 * All signal values are as on the CAN bus.
 */
